pub fn rle(input: &str) -> String {
    let mut out = Vec::new();
    for (i, c) in input.chars().enumerate() {
        let mut count = 1;
        while i + 1 < input.len() && input.chars().nth(i + 1) == Some(c) {
            count += 1;
            i += 1;
        }
        out.push_str(&format!("{}{}", c, count));
    }
    out.join("")
}

