pub fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes: Vec<u32> = Vec::new();
    for i in 2..=n {
        let mut is_prime = true;
        for j in 2..=((i as f64).sqrt() as u32) {
            if i % j == 0 {
                is_prime = false;
                break;
            }
        }
        if is_prime {
            primes.push(i);
        }
    }
    primes
}

