pub fn word_count(text: &str) -> std::collections::HashMap<String, usize> {
    let mut words: HashMap<String, usize> = HashMap::new();
    for word in text
        .split_whitespace()
        .filter(|s| !s.is_empty() && s.chars().all(char::is_alphanumeric))
    {
        *words.entry(word.to_lowercase()).or_insert(0) += 1;
    }
    words
}

