pub fn max_subarray(v: &[i64]) -> i64 {
    if v.is_empty() {
        return 0;
    }
    let mut max_so_far = v[0];
    let mut max_ending_here = v[0];
    for &x in v.iter().skip(1) {
        max_ending_here = x.max(max_ending_here + x);
        max_so_far = max(max_so_far, max_ending_here);
    }
    max_so_far
}

