pub fn to_binary(n: u32) -> String {
    let mut binary = String::new();
    let mut current = n;

    while current != 0 {
        binary = format!("1{}", binary);
        current >>= 1;
    }

    if binary.is_empty() {
        binary.push('0');
    }

    binary
}

