pub fn from_roman(s: &str) -> Option<u32> {
    let mut total: u32 = 0;
    for c in s.chars() {
        match c {
            'I' => total += 1,
            'V' => total += 5,
            'X' => total += 10,
            'L' => total += 50,
            'C' => total += 100,
            'D' => total += 500,
            'M' => total += 1000,
            _ => return None,
        }
    }
    Some(total)
}

