pub fn merge_sorted(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut merged = Vec::new();
    let mut i = 0;
    let mut j = 0;

    while i < a.len() && j < b.len() {
        if a[i] < b[j] {
            merged.push(a[i]);
            i += 1;
        } else {
            merged.push(b[j]);
            j += 1;
        }
    }

    while i < a.len() {
        merged.push(a[i]);
        i += 1;
    }

    while j < b.len() {
        merged.push(b[j]);
        j += 1;
    }

    merged
}

