pub fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    let mut rows = m.len();
    let mut cols = m[0].len();
    let mut transposed = vec![vec![0; cols]; rows];

    for (i, row) in m.iter().enumerate() {
        for (j, col) in row.iter().enumerate() {
            transposed[j][i] = *col;
        }
    }

    transposed
}

