pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 6 {
        return None;
    }

    let (r, g, b) = s
        .chars()
        .map(|c| c.to_digit(16))
        .collect::<Result<Vec<u8>, _>>()
        .map(|v| v.into_iter().map(|d| d.to_digit(16).unwrap()).collect::<Vec<u8>>())
        .ok()?;

    Some((r, g, b))
}

