    let len = v.len();
    let k = k % len;
    if k == 0 {
        return v.to_vec();
    }
    let mut out = Vec::with_capacity(len);
    for i in 0..k {
        out.push(v[i]);
    }
    for i in k..len {
        out.push(v[i - k]);
    }
    out
}

